import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { schema } from "@/server/db";
import { useFreshDb } from "@/server/test/db";
import { upsertUser } from "@/server/auth/session";
import { isInstanceAdmin } from "@/server/admin-identity";
import { grantInstanceAdmin, listInstanceAdmins, revokeInstanceAdmin } from "@/server/instance-admins";

let ctx: Awaited<ReturnType<typeof useFreshDb>>;
// Database ids are generated by upsertUser, so the tests use the ids it returns.
let root: string;
let alice: string;
let bob: string;
let carol: string;

beforeAll(async () => {
  ctx = await useFreshDb();
  root = (await upsertUser({ id: "hc-root", name: "Root", email: "root@example.com", slackId: null, emailVerified: true })).id;
  alice = (await upsertUser({ id: "hc-alice", name: "Alice", email: "alice@example.com", slackId: null, emailVerified: true })).id;
  bob = (await upsertUser({ id: "hc-bob", name: "Bob", email: "bob@example.com", slackId: null, emailVerified: false })).id;
  carol = (await upsertUser({ id: "hc-carol", name: "Carol", email: null, slackId: null })).id;
  process.env.SECURITY_REPORT_ADMIN_ID = root;
});
afterAll(async () => {
  delete process.env.SECURITY_REPORT_ADMIN_ID;
  await ctx.cleanup();
});

describe("instance administrators", () => {
  it("refuses a change from an account that is not an administrator", async () => {
    await expect(grantInstanceAdmin(carol, { email: "alice@example.com" }, true)).rejects.toMatchObject({
      status: 403,
      code: "forbidden",
    });
    await expect(listInstanceAdmins(carol)).rejects.toMatchObject({ status: 403 });
  });

  it("needs a fresh Hack Club sign-in before any change", async () => {
    await expect(grantInstanceAdmin(root, { email: "alice@example.com" }, false)).rejects.toMatchObject({
      status: 403,
      code: "reauth_required",
    });
    expect(await isInstanceAdmin(alice)).toBe(false);
  });

  it("grants administration to a verified email, and only once", async () => {
    const first = await grantInstanceAdmin(root, { email: "  Alice@Example.com " }, true);
    expect(first).toMatchObject({ userId: alice, changed: true });
    expect(await isInstanceAdmin(alice)).toBe(true);

    const again = await grantInstanceAdmin(root, { email: "alice@example.com" }, true);
    expect(again).toMatchObject({ userId: alice, changed: false });
  });

  it("will not grant to an unverified email, so a typed address cannot claim someone else's account", async () => {
    await expect(grantInstanceAdmin(root, { email: "bob@example.com" }, true)).rejects.toMatchObject({ status: 404 });
    expect(await isInstanceAdmin(bob)).toBe(false);
  });

  it("lets a granted administrator see the list", async () => {
    const listing = await listInstanceAdmins(alice);
    expect(listing.configured?.userId).toBe(root);
    expect(listing.granted.map((g) => g.userId)).toContain(alice);
  });

  it("removes a granted administrator, and never the configured one", async () => {
    await expect(revokeInstanceAdmin(root, { userId: root }, true)).rejects.toMatchObject({ status: 400 });
    expect(await isInstanceAdmin(root)).toBe(true);

    expect(await revokeInstanceAdmin(root, { userId: alice }, true)).toMatchObject({ changed: true });
    expect(await isInstanceAdmin(alice)).toBe(false);

    const left = await ctx.db
      .select()
      .from(schema.instanceAdmins)
      .where(eq(schema.instanceAdmins.userId, alice))
      .get();
    expect(left).toBeUndefined();
  });
});
